import functools
from typing import ForwardRef, get_type_hints
from fastapi.dependencies.utils import get_typed_signature, get_typed_return_annotation
import inspect

# Define a class to use as a forward reference
class MyModel:
    pass

def original_func(a: "MyModel") -> "MyModel":
    return a

def wrapper_module():
    # This simulates the function being wrapped in a different module/context
    # where MyModel is not in globals.
    @functools.wraps(original_func)
    def wrapped_func(a):
        return original_func(a)
    return wrapped_func

def test_repro():
    wrapped = wrapper_module()

    print(f"Wrapped function: {wrapped}")
    print(f"Wrapped globals: {wrapped.__globals__ is original_func.__globals__}")

    try:
        sig = get_typed_signature(wrapped)
        print("get_typed_signature succeeded")
        for param in sig.parameters.values():
            print(f"Param {param.name}: {param.annotation}")
    except Exception as e:
        print(f"get_typed_signature failed: {e}")
        import traceback
        traceback.print_exc()

    try:
        ret_ann = get_typed_return_annotation(wrapped)
        print(f"get_typed_return_annotation succeeded: {ret_ann}")
    except Exception as e:
        print(f"get_typed_return_annotation failed: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    test_repro()

